using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using pcms.Application.Inventory;
namespace pcms.Api.Controllers;
[ApiController,Route("api/inventory/stock-counts")] public sealed class InventoryStockCountsController(IStockCountService service):ControllerBase{[HttpGet("{supplyItemId:guid}"),Authorize(Policy="Inventory.View")]public Task<IEnumerable<StockCountDto>> Get(Guid supplyItemId)=>service.GetAsync(supplyItemId);[HttpPost,Authorize(Policy="Inventory.Manage")]public async Task<ActionResult<StockCountDto>> Post(StockCountInput input){try{Guid? u=Guid.TryParse(User.FindFirstValue(ClaimTypes.NameIdentifier),out var id)?id:null;return Ok(await service.RecordAsync(input,u));}catch(ArgumentException e){return BadRequest(new{message=e.Message});}catch(InvalidOperationException e){return Conflict(new{message=e.Message});}}}
